export default async function(app){
 const reactive=await app.import('esri/core/reactiveUtils');const MosaicRule=await app.import('esri/layers/support/MosaicRule');const root=app.getMount('temporal-comparison');const sources=app.config.sources;let proposal=null,serial=0,active=null,disposed=false;
 const el=(tag,text,parent)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(parent)parent.append(n);return n;};
 const menu=el('details',null,root);Object.assign(menu.style,{border:'1px solid var(--calcite-color-border-2)',borderRadius:'8px',padding:'10px',color:'var(--calcite-color-text-1)',fontSize:'13px'});const head=el('summary','🕒 Comparación temporal A/B',menu);head.style.cssText='cursor:pointer;font-weight:600;font-size:15px';const body=el('div',null,menu);body.style.cssText='display:grid;gap:10px;padding-top:12px;min-width:0';el('small','Propón dos periodos del mismo servicio. Revisar no modifica el mapa; preparar A/B requiere pulsar la confirmación.',body);
 const field=(name,type,parent)=>{const label=el('label',name,parent);label.style.cssText='display:grid;gap:4px';const input=el('input',null,label);input.type=type;input.style.cssText='box-sizing:border-box;width:100%;padding:8px;color:var(--calcite-color-text-1);background:var(--calcite-color-foreground-1);border:1px solid var(--calcite-color-border-2);border-radius:4px';return input};
 const service=el('select',null,body);service.setAttribute('aria-label','Servicio para la comparación');service.style.cssText='width:100%;padding:8px;color:var(--calcite-color-text-1);background:var(--calcite-color-foreground-1)';for(const s of sources){const o=el('option',s.title,service);o.value=s.id}const yr=new Date().getUTCFullYear();const grid=el('div',null,body);grid.style.cssText='display:grid;grid-template-columns:1fr 1fr;gap:8px;min-width:0';const older=el('div',null,grid),newer=el('div',null,grid);older.style.cssText=newer.style.cssText='display:grid;gap:5px;min-width:0';el('strong','A · anterior',older);const af=field('Desde','date',older),at=field('Hasta','date',older);el('strong','B · posterior',newer);const bf=field('Desde','date',newer),bt=field('Hasta','date',newer);af.value=(yr-1)+'-01-01';at.value=(yr-1)+'-12-31';bf.value=yr+'-01-01';bt.value=yr+'-12-31';const max=field('Nubosidad máxima por escena (%)','number',body);max.min='0';max.max='100';max.step='1';max.value='30';const status=el('div','Selecciona periodos y consulta los pares.',body);status.setAttribute('role','status');status.setAttribute('aria-live','polite');const results=el('div',null,body);results.style.cssText='display:grid;gap:9px;min-width:0';
 const btn=(text,parent,fn)=>{const b=el('button',text,parent);b.type='button';b.style.cssText='cursor:pointer;padding:9px;text-align:left;border-radius:4px;border:1px solid var(--calcite-color-border-2);color:var(--calcite-color-text-1);background:var(--calcite-color-foreground-2)';b.onclick=()=>Promise.resolve(fn()).catch(e=>{status.textContent='No se pudo completar: '+(e.message||e)});return b};
 const labelDate=t=>t==null?'Sin fecha':new Date(t).toLocaleDateString('es-ES',{timeZone:'UTC'});const signature=()=>JSON.stringify({source:service.value,a:[af.value,at.value],b:[bf.value,bt.value],cloud:max.value,extent:app.view.extent?.toJSON()||null});function invalidate(){proposal=null;serial++;results.replaceChildren();status.textContent='Los parámetros cambiaron. Consulta de nuevo antes de preparar A/B.'}
 for(const n of [service,af,at,bf,bt,max])n.addEventListener('change',invalidate);
 function check(){const s=sources.find(x=>x.id===service.value);if(!s)throw Error('Servicio desconocido');for(const n of [af,at,bf,bt])if(!/^\d{4}-\d{2}-\d{2}$/.test(n.value)||Number.isNaN(Date.parse(n.value)))throw Error('Indica las cuatro fechas válidas');if(af.value>at.value||bf.value>bt.value||at.value>=bf.value)throw Error('Los dos periodos deben ser válidos, separados y A anterior a B');const cloud=Number(max.value);if(!Number.isInteger(cloud)||cloud<0||cloud>100)throw Error('La nubosidad debe ser un entero entre 0 y 100');if(!app.view.extent)throw Error('La vista no está disponible');return {s,cloud,extent:app.view.extent.clone()}}
 async function candidates(s,cloud,extent,from,to,token){const layer=app.layers[s.layerId];await layer.load();const end=new Date(Date.parse(to+'T00:00:00Z')+86400000).toISOString().slice(0,10);const where="acquisitiondate >= timestamp '"+from+" 00:00:00' AND acquisitiondate < timestamp '"+end+" 00:00:00'"+(cloud<100?' AND cloudcover >= 0 AND cloudcover <= '+cloud:'');const ids=[...new Set(await layer.queryObjectIds({where,geometry:extent,spatialRelationship:'intersects'}))];if(ids.length>16000)throw Error('Hay '+ids.length+' escenas en un periodo. Acota las fechas o acerca el mapa; no se omitirán escenas silenciosamente');const found=new Map();for(let i=0;i<ids.length;i+=500){if(token!==serial||disposed)return null;const set=await layer.queryRasters({objectIds:ids.slice(i,i+500),outFields:['objectid','name','acquisitiondate','cloudcover',s.sensorField],returnGeometry:false});for(const f of set.features){const a=f.attributes;found.set(String(a[layer.objectIdField]),{id:a[layer.objectIdField],name:a.name??null,date:a.acquisitiondate??null,cloud:a.cloudcover??null,sensor:a[s.sensorField]??null})}}if(found.size!==ids.length)throw Error('El servicio no devolvió los metadatos completos de este periodo');return [...found.values()].filter(x=>x.date!=null).sort((a,b)=>(a.cloud==null?101:Number(a.cloud))-(b.cloud==null?101:Number(b.cloud))||(b.date||0)-(a.date||0)).slice(0,12)}
 function graph(a,b){const bar=el('div',null,results);bar.style.cssText='display:grid;gap:4px;padding:9px;border:1px solid var(--calcite-color-border-2);border-radius:4px';el('strong','Indicadores de las escenas propuestas · metadatos',bar);for(const [k,v] of [['A',a],['B',b]]){const row=el('div',null,bar);row.style.cssText='display:grid;grid-template-columns:20px 1fr 50px;gap:6px;align-items:center';el('span',k,row);const track=el('div',null,row);track.style.cssText='height:9px;border-radius:4px;background:var(--calcite-color-foreground-3)';const fill=el('div',null,track);fill.style.cssText='height:9px;border-radius:4px;background:var(--calcite-color-brand);width:'+Math.max(0,Math.min(100,Number(v.cloud)||0))+'%';el('span',v.cloud==null?'s/d':Number(v.cloud).toFixed(1)+'%',row)}const days=Math.round((b.date-a.date)/86400000);el('small','Separación: '+days+' días. Las barras muestran nubosidad de la escena completa, no cambio entre píxeles.',bar)}
 function renderPairs(p){results.replaceChildren();if(!p.pairs.length){el('div','No hay un par verificable en ambos periodos. Amplía las fechas o el umbral de nubosidad.',results);return}el('small','Pares del catálogo completo en esta extensión: prioridad a nubosidad registrada baja; empate por fecha reciente. La intersección de huellas no garantiza cobertura completa ni coincidencia espacial.',results);p.pairs.forEach((pair,i)=>{const card=el('div',null,results);card.style.cssText='padding:9px;border:1px solid var(--calcite-color-border-2);border-radius:6px;display:grid;gap:6px;overflow-wrap:anywhere';el('strong','Par '+(i+1)+' · '+labelDate(pair.a.date)+' → '+labelDate(pair.b.date),card);for(const [k,v] of [['A',pair.a],['B',pair.b]])el('small',k+' · '+(v.name||'Escena '+v.id)+' · '+labelDate(v.date)+' · '+(v.cloud==null?'nubosidad sin dato':Number(v.cloud).toFixed(1)+' % nubes')+(v.sensor?' · '+v.sensor:''),card);btn('Revisar este par',card,()=>{if(proposal!==p||signature()!==p.signature){invalidate();throw Error('La vista o los filtros cambiaron; consulta otra vez')}p.chosen=i;renderPairs(p);graph(pair.a,pair.b);confirm.hidden=false;confirm.textContent='Confirmar y preparar A/B: '+labelDate(pair.a.date)+' → '+labelDate(pair.b.date)});if(p.chosen===i)card.style.borderColor='var(--calcite-color-brand)'});if(p.chosen!=null){graph(p.pairs[p.chosen].a,p.pairs[p.chosen].b)}}
 const propose=btn('Buscar pares verificables',body,async()=>{const token=++serial;proposal=null;results.replaceChildren();confirm.hidden=true;status.textContent='Consultando ambos periodos; el mapa no se modificará…';try{const {s,cloud,extent}=check(),sig=signature();const a=await candidates(s,cloud,extent,af.value,at.value,token);if(token!==serial||disposed)return {stale:true};const b=await candidates(s,cloud,extent,bf.value,bt.value,token);if(token!==serial||disposed)return {stale:true};const pairs=[];for(const x of a)for(const y of b)if(x.id!==y.id&&x.date<y.date)pairs.push({a:x,b:y});pairs.sort((x,y)=>((x.a.cloud==null?101:Number(x.a.cloud))+(x.b.cloud==null?101:Number(x.b.cloud)))-((y.a.cloud==null?101:Number(y.a.cloud))+(y.b.cloud==null?101:Number(y.b.cloud)))||(y.b.date||0)-(x.b.date||0));const usedA=new Set(),usedB=new Set(),top=[];for(const pair of pairs){if(usedA.has(String(pair.a.id))||usedB.has(String(pair.b.id)))continue;top.push(pair);usedA.add(String(pair.a.id));usedB.add(String(pair.b.id));if(top.length===3)break}if(sig!==signature())throw Error('La vista cambió durante la búsqueda');proposal={signature:sig,source:s.id,cloud,pairs:top,chosen:null,counts:{a:a.length,b:b.length},token};renderPairs(proposal);status.textContent=top.length?'Se encontraron '+top.length+' pares candidatos. Revisa uno y confirma antes de cambiar el mapa.':'No hay pares con los periodos y filtros elegidos.';return {source:s.id,periodA:[af.value,at.value],periodB:[bf.value,bt.value],cloudMax:cloud,pairs:top,sceneSamples:{a:a.length,b:b.length},mapChanged:false}}catch(e){if(token===serial){status.textContent='No se pudo proponer un par: '+(e.message||e);results.replaceChildren()}return {error:e.message||String(e)}}});
 const confirm=btn('Confirmar y preparar A/B',body,async()=>{const p=proposal;if(!p||p.chosen==null||p.signature!==signature()||p.token!==serial)throw Error('La propuesta caducó; consulta los pares de nuevo');const {s,cloud,extent}=check();const pair=p.pairs[p.chosen],layer=app.layers[s.layerId];status.textContent='Verificando las dos escenas antes de preparar A/B…';const checkIds=await layer.queryObjectIds({where:'objectid IN ('+Number(pair.a.id)+','+Number(pair.b.id)+')',geometry:extent,spatialRelationship:'intersects'});if(p!==proposal||p.signature!==signature()||p.token!==serial)throw Error('La vista cambió; consulta otra vez');if(!checkIds.map(String).includes(String(pair.a.id))||!checkIds.map(String).includes(String(pair.b.id)))throw Error('Una escena ya no intersecta la vista');const verify=await layer.queryRasters({objectIds:[Number(pair.a.id),Number(pair.b.id)],outFields:['objectid','acquisitiondate','cloudcover'],returnGeometry:false});if(p!==proposal||p.signature!==signature()||p.token!==serial)throw Error('La vista cambió; consulta otra vez');for(const item of [pair.a,pair.b]){const row=verify.features.find(f=>String(f.attributes[layer.objectIdField])===String(item.id))?.attributes;if(!row||row.acquisitiondate!==item.date||row.cloudcover!==item.cloud||cloud<100&&(row.cloudcover==null||row.cloudcover>cloud))throw Error('Los metadatos de una escena cambiaron; consulta otra vez')}
 const a=layer.clone(),b=layer.clone();a.id='temporal-reference-a';b.id='temporal-reference-b';a.title='Comparación A · '+labelDate(pair.a.date);b.title='Comparación B · '+labelDate(pair.b.date);a.mosaicRule=new MosaicRule({method:'lock-raster',lockRasterIds:[Number(pair.a.id)],operation:'first'});b.mosaicRule=new MosaicRule({method:'lock-raster',lockRasterIds:[Number(pair.b.id)],operation:'first'});a.visible=false;b.visible=true;const previous=active;const originalVisibility=sources.map(x=>({id:x.layerId,visible:app.layers[x.layerId].visible}));try{app.map.addMany([a,b]);for(const x of sources)app.layers[x.layerId].visible=false;active={a,b,source:s.id,pair,originalVisibility,side:'B'};if(previous){app.map.removeMany([previous.a,previous.b]);previous.a.destroy();previous.b.destroy()}proposal=null;confirm.hidden=true;showControls();status.textContent='Comparación preparada: B visible. Usa «Ver A/B» o finaliza para restaurar las capas previas.';return {confirmed:true,source:s.id,a:{id:pair.a.id,date:pair.a.date},b:{id:pair.b.id,date:pair.b.date},visible:'B'}}catch(e){app.map.removeMany([a,b]);a.destroy();b.destroy();for(const x of originalVisibility)if(!previous)app.layers[x.id].visible=x.visible;throw e}});confirm.hidden=true;
 const actions=el('div',null,body);actions.style.cssText='display:flex;gap:6px';const toggle=btn('Ver A',actions,()=>{if(!active)throw Error('No hay comparación preparada');active.side=active.side==='A'?'B':'A';active.a.visible=active.side==='A';active.b.visible=active.side==='B';showControls();return {visible:active.side,a:active.pair.a.id,b:active.pair.b.id}});const end=btn('Finalizar comparación',actions,()=>{if(!active)return {active:false};stop();status.textContent='Comparación finalizada; se han restaurado las capas de origen.';return {active:false}});function showControls(){actions.hidden=!active;toggle.textContent=active?.side==='A'?'Ver B':'Ver A';}actions.hidden=true;
 function stop(){if(!active)return;const old=active;active=null;app.map.removeMany([old.a,old.b]);old.a.destroy();old.b.destroy();for(const x of old.originalVisibility)app.layers[x.id].visible=x.visible;showControls()}
 const viewWatch=reactive.watch(()=>[app.view.stationary,app.view.extent?.xmin,app.view.extent?.ymin,app.view.extent?.xmax,app.view.extent?.ymax],()=>{if(proposal&&proposal.signature!==signature()){proposal=null;serial++;confirm.hidden=true;results.replaceChildren();status.textContent='La vista cambió; vuelve a buscar pares.'}});app.actions.register('temporal-propose',()=>propose.click());app.actions.register('temporal-state',()=>({proposal:proposal?{source:proposal.source,pairs:proposal.pairs,chosen:proposal.chosen,signatureValid:proposal.signature===signature()}:null,active:active?{source:active.source,side:active.side,a:active.pair.a.id,b:active.pair.b.id}:null,menuOpen:menu.open,status:status.textContent}));app.onCleanup(()=>{disposed=true;serial++;viewWatch.remove();stop();root.replaceChildren()});
}